FoamFile
{
    version     2.0;
    format      ascii;
    class       pointVectorField;
    object      pointMotionU;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

dimensions      [0 1 0 0 0 0 0];

internalField   uniform (0 0 0);

boundaryField
{
    air_to_flap
    {
        type            globalInterpolated;
        nbrName         U;
        value           uniform (0 0 0);
    }
    ground
    {
        type            slip;
    }
    outlet
    {
        type            slip;
    }
}

